const jsonData = pm.response.json();
pm.environment.set("access_token", jsonData.accessToken);
console.log(pm.environment.get("access_token"));

pm.test("Status code is 200", ()=> {
    pm.response.to.have.status(200);
});

pm.test("Response contains accessToken", () => {
    pm.expect(jsonData).to.have.property('accessToken');
});

pm.test("accessToken is not empty", () => {
    pm.expect(jsonData.accessToken).to.not.be.empty;
});

pm.test("accessToken is a string", () => {
    pm.expect(jsonData.accessToken).to.be.a('string');
});

pm.test("response time", ()=>{
    pm.expect(pm.response.responseTime).to.be.below(2000);
})

pm.test("Content-Type header is present", ()=>{
    pm.response.to.have.header('Content-Type');
})

pm.test("Content-Type header has application/json; charset=utf-8 ", ()=>{
    pm.expect(pm.response.headers.get("Content-Type")).to.eql('application/json; charset=utf-8')
})

